static uint64_t wc_net_now_ms(void)
{
#if defined(_WIN32) || defined(__MINGW32__)
    return (uint64_t)GetTickCount64();
#else
    struct timespec now;
    if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) return 0;
