#endif
}

uint64_t wc_net_deadline_after(int timeout_ms)
{
    uint64_t now = wc_net_now_ms();
    return timeout_ms > 0 ? now + (uint64_t)timeout_ms : now;
}

static int wc_net_deadline_remaining(uint64_t deadline_ms)
{
